/**
 * CleanIndiaOutline — renders a high-quality India map image generated by Gemini AI.
 * Uses an <image> SVG element so it sits in the same coordinate space as the
 * LocationNode dots, which are positioned using x/y percentages derived from
 * the MAP_VIEWPORT constant.
 *
 * The map image (india_map_south_highlighted.png) was AI-generated with accurate
 * state boundaries and South India highlighted in the brand blue #2563EB.
 */
export default function CleanIndiaOutline({ accentColor }) {
  // We don't actually use accentColor here because the image already has the
  // correct highlight colours baked in. The prop is kept for API compatibility.
  return (
    <image
      href="/images/india_map_south_highlighted.png"
      x="0"
      y="0"
      width="100%"
      height="100%"
      preserveAspectRatio="xMidYMid meet"
      style={{ opacity: 1 }}
    />
  );
}
